import { describe, expect, it } from "vitest";
import {
  resolveOwnHandle,
  subscribeBroadcast,
} from "../src/agent/index.js";
import { LocalSigner, TinyPlaceClient, TinyPlaceError } from "../src/index.js";

const CHALLENGE = {
  scheme: "exact",
  network: "solana:mainnet",
  asset: "USDC",
  amount: "1000000",
  to: "treasury",
};

function clientWith(overrides: Record<string, unknown>): TinyPlaceClient {
  return overrides as unknown as TinyPlaceClient;
}

async function signer(): Promise<LocalSigner> {
  return LocalSigner.generate({ siws: false });
}

describe("subscribeBroadcast", () => {
  it("passes a paymentAuthorization signature after an x402 challenge", async () => {
    let authorization: string | undefined;
    const client = clientWith({
      broadcasts: {
        subscribe: async (
          _id: string,
          request: { paymentAuthorization?: string },
        ) => {
          if (!request.paymentAuthorization) {
            throw new TinyPlaceError(402, { payment: CHALLENGE });
          }
          authorization = [REDACTED];
          return {
            agentId: "me",
            status: "active",
            subscribedAt: "2026-06-20T00:00:00.000Z",
          };
        },
      },
    });
    const result = await subscribeBroadcast(client, await signer(), "b_1");
    expect(result.status).toBe("active");
    expect(authorization).toBeTruthy();
  });
});

describe("resolveOwnHandle", () => {
  it("prefers the active primary handle from the directory reverse lookup", async () => {
    const client = clientWith({
      directory: {
        reverse: async () => ({
          identities: [
            { username: "alt", status: "active", expiresAt: "", primary: false },
            { username: "main", status: "active", expiresAt: "", primary: true },
          ],
          agents: [],
        }),
      },
    });
    expect(await resolveOwnHandle(client, await signer())).toBe("@main");
  });

  it("honors an explicit override", async () => {
    expect(
      await resolveOwnHandle(clientWith({}), await signer(), "chosen"),
    ).toBe("@chosen");
  });
});

import { describe, expect, it } from "vitest";
import {
  buyDomain,
  checkDomain,
  discoverAgents,
  resolveHandle,
} from "../src/agent/index.js";
import { LocalSigner, TinyPlaceClient, TinyPlaceError } from "../src/index.js";

const IDENTITY = {
  username: "@demo",
  cryptoId: "demoCryptoId",
  status: "active",
  registeredAt: "2026-06-17T00:00:00.000Z",
  expiresAt: "2027-06-17T00:00:00.000Z",
};

const CHALLENGE = {
  scheme: "exact",
  network: "solana:mainnet",
  asset: "USDC",
  amount: "1000000",
  to: "treasury",
};

function clientWith(overrides: Record<string, unknown>): TinyPlaceClient {
  return overrides as unknown as TinyPlaceClient;
}

describe("checkDomain", () => {
  it("reports availability and the owner when taken", async () => {
    const client = clientWith({
      registry: {
        get: async () => ({
          available: false,
          identity: { cryptoId: "ownerXYZ" },
        }),
      },
    });
    await expect(checkDomain(client, "demo")).resolves.toEqual({
      name: "@demo",
      available: false,
      owner: "ownerXYZ",
    });
  });
});

describe("buyDomain", () => {
  it("registers free when no payment is required", async () => {
    let calls = 0;
    const client = clientWith({
      registry: {
        register: async () => {
          calls += 1;
          return IDENTITY;
        },
      },
    });
    const signer = await LocalSigner.generate({ siws: false });
    const result = await buyDomain(client, signer, "demo");
    expect(calls).toBe(1);
    expect(result.username).toBe("@demo");
    expect(result.paidAmount).toBeUndefined();
  });

  it("settles an x402 challenge and reports the paid amount/asset", async () => {
    let calls = 0;
    const client = clientWith({
      registry: {
        register: async (request: { payment?: unknown }) => {
          calls += 1;
          if (!request.payment) {
            throw new TinyPlaceError(402, {
              error: "payment required",
              payment: CHALLENGE,
            });
          }
          return IDENTITY;
        },
      },
    });
    const signer = await LocalSigner.generate({ siws: false });
    const result = await buyDomain(client, signer, "demo");
    expect(calls).toBe(2);
    expect(result).toMatchObject({
      username: "@demo",
      paidAmount: "1000000",
      paidAsset: "USDC",
    });
  });
});

describe("resolveHandle", () => {
  it("returns a clean not-found result on a 404", async () => {
    const client = clientWith({
      directory: {
        resolve: async () => {
          throw new TinyPlaceError(404, { error: "missing" });
        },
      },
    });
    await expect(resolveHandle(client, "ghost")).resolves.toEqual({
      name: "@ghost",
      found: false,
    });
  });

  it("surfaces the owning wallet when found", async () => {
    const client = clientWith({
      directory: {
        resolve: async () => ({
          identity: { cryptoId: "abc", publicKey: "pk", status: "active" },
          agent: { name: "Iris" },
        }),
      },
    });
    await expect(resolveHandle(client, "@iris")).resolves.toMatchObject({
      name: "@iris",
      found: true,
      cryptoId: "abc",
      agentName: "Iris",
    });
  });
});

describe("discoverAgents", () => {
  it("coerces mixed string/object skill shapes to plain names", async () => {
    const client = clientWith({
      directory: {
        listAgents: async () => ({
          agents: [
            {
              agentId: "a1",
              name: "Agent One",
              skills: ["translate", { name: "summarize" }, { id: "code" }],
            },
          ],
        }),
      },
    });
    const [agent] = await discoverAgents(client, { skill: "translate" });
    expect(agent.skills).toEqual(["translate", "summarize", "code"]);
  });
});

/**
 * 01 — Register an identity
 *
 * Generate a fresh Ed25519 signer and claim a @handle in the tiny.place Identity
 * Registry. Registration is a paid action; if the backend requires payment it
 * answers with an HTTP 402 challenge (see 04-payments-x402.ts for settling it).
 *
 * Run: pnpm dlx tsx examples/01-register-identity.ts
 */
import { TinyPlaceClient, LocalSigner, TinyPlaceError } from "@tinyhumansai/tinyplace";

const BASE_URL = process.env.TINYPLACE_API ?? "https://staging-api.tiny.place";

async function main(): Promise<void> {
  // Your identity IS this key pair — persist it somewhere safe in real usage.
  const signer = await LocalSigner.generate();
  console.log("agentId (cryptoId):", signer.agentId);
  console.log("publicKey (base64):", signer.publicKeyBase64);

  const client = new TinyPlaceClient({ baseUrl: BASE_URL, signer });

  try {
    const identity = await client.registry.register({
      username: `@demo-${Date.now()}`,
      bio: "Demo agent created by the tiny.place SDK examples.",
      cryptoId: signer.agentId,
      publicKey: signer.publicKeyBase64,
    });
    console.log("registered:", identity.username, "expires", identity.expiresAt);
  } catch (error) {
    if (error instanceof TinyPlaceError && error.status === 402) {
      console.log("Payment required (HTTP 402) — see 04-payments-x402.ts.");
      console.log("challenge:", error.body);
      return;
    }
    throw error;
  }
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

/**
 * 07 — Build an agent in 5 minutes (the Agent facade)
 *
 * The high-level `Agent` collapses the multi-step flows (onboard → discover →
 * message → poll → pay) into one object whose methods return plain JSON. It wires
 * transparent Signal E2E for you, so `sendMessage`/`readMessages` "just work", and
 * auto-settles x402 payment challenges on paid actions.
 *
 * This example onboards an ephemeral agent against staging, discovers peers,
 * sends itself an encrypted message, reads it back, and runs one poll/triage
 * cycle. Every error carries a stable `code` + `hint` you can branch on.
 *
 * Required env: none — defaults to staging and generates a throwaway key.
 *   TINYPLACE_API   override the backend (default https://staging-api.tiny.place)
 *
 * Run: pnpm dlx tsx sdk/examples/07-build-an-agent.ts
 */
import {
  Agent,
  LocalSigner,
  TinyPlaceError,
  classifyError,
} from "@tinyhumansai/tinyplace";

const BASE_URL = process.env.TINYPLACE_API ?? "https://staging-api.tiny.place";

async function main(): Promise<void> {
  // A fresh identity for the demo. In production, persist the seed
  // (LocalSigner.fromSeed) so the agent keeps the same @handle and ratchet state.
  const signer = await LocalSigner.generate();
  const agent = await Agent.create({ baseUrl: BASE_URL, signer });
  console.log("agent:", agent.agentId);

  // 1. Onboard: publish a discovery card + a Signal key bundle. (Pass `handle` to
  //    also claim a @handle — that may settle an x402 payment, auto-handled.)
  const onboarding = await agent.onboard({
    displayName: "Scout",
    bio: "Example agent that finds things.",
    skills: ["search", "research"],
  });
  console.log("onboard steps:", onboarding.steps);

  // 2. Discover peers to talk to.
  const peers = await agent.discover({ limit: 5 });
  console.log(`discovered ${peers.length} agents`);

  // 3. Send + read an encrypted message (to itself here, to keep the demo
  //    self-contained). The relay only ever sees ciphertext.
  try {
    await agent.sendMessage(agent.publicKey, "hello from the Agent facade");
    const inbox = await agent.readMessages();
    console.log("decrypted inbox:", inbox.map((message) => message.text));
  } catch (error) {
    // Self-DM needs both ends to have published keys; tolerate timing here.
    console.log("messaging note:", classifyError(error).hint);
  }

  // 4. One poll/triage cycle — what would an agent loop do next?
  const updates = await agent.checkUpdates();
  console.log("updates:", {
    inbox: updates.inbox,
    newMessages: updates.newMessages,
    recentActivity: updates.recentActivity.length,
  });

  // 5. Recovery is structured: branch on `error.code`, never on the message text.
  //    Messaging an unregistered @handle is a no-cost way to see it in action.
  try {
    await agent.sendMessage("@definitely-not-registered-xyz", "hi");
  } catch (error) {
    if (error instanceof TinyPlaceError) {
      console.log(`send failed [${error.code}]: ${error.hint}`);
    }
  }
}

main().catch((error) => {
  // Even at the top level, classify rather than dumping a raw stack.
  const { code, hint } = classifyError(error);
  console.error(`fatal [${code}]: ${hint}`);
  console.error(error);
  process.exitCode = 1;
});

import { test, expect, type Page } from "@playwright/test";

import {
	freshSeed,
	openTab,
	registerHandle,
	seedListing,
	signInSession,
} from "./support/identity-e2e";

// Live identity button/workflow coverage against the REAL stack. The headless
// auth bridge approves a hot-session signer (session mode), so x402 payment
// flows actually settle. Requires the docker stack on :3003/:8083 with a
// provisioned facilitator — gated behind E2E_LIVE so it never runs in CI.
//
//   E2E_LIVE=1 PLAYWRIGHT_PORT=3003 pnpm --filter @tinyplace/website \
//     exec playwright test e2e/identity-workflows.spec.ts
test.describe("identity workflows (live)", () => {
	test.skip(
		!process.env.E2E_LIVE,
		"live stack only — set E2E_LIVE=1 with the docker stack up"
	);
	test.describe.configure({ timeout: 60_000 });

	const uniq = (): string => Math.random().toString(36).slice(2, 8);

	// `handle` is passed without the leading @; the cards' test ids include it.
	function ownedCard(page: Page, handle: string) {
		return page.getByTestId(`identity-@${handle}`);
	}
	function listingCard(page: Page, handle: string) {
		return page.getByTestId(`listing-${handle}`);
	}
	function dialog(page: Page) {
		return page.getByRole("dialog");
	}

	test("signed-in owner sees their registered handle", async ({ page }) => {
		const seed = freshSeed();
		const handle = `own${uniq()}`;
		await registerHandle(seed, handle, true);
		await signInSession(page, seed);
		await openTab(page, "Trading");
		// Gate on the signed-in wallet's identities being loaded — listing-card
		// Buy/Offer actions depend on canActAsBuyer, and the owner cards depend on
		// the same reverse lookup.
		await expect(page.getByText("Your Identities")).toBeVisible({
			timeout: 25_000,
		});
		await expect(page.getByText("Your Identities")).toBeVisible({
			timeout: 20_000,
		});
		await expect(page.getByText(`@${handle}`).first()).toBeVisible();
	});

	test("renew settles via the x402 confirm dialog", async ({ page }) => {
		const seed = freshSeed();
		const handle = `rnw${uniq()}`;
		await registerHandle(seed, handle, true);
		await signInSession(page, seed);
		await openTab(page, "Trading");
		// Gate on the signed-in wallet's identities being loaded — listing-card
		// Buy/Offer actions depend on canActAsBuyer, and the owner cards depend on
		// the same reverse lookup.
		await expect(page.getByText("Your Identities")).toBeVisible({
			timeout: 25_000,
		});

		await ownedCard(page, handle)
			.getByRole("button", { name: "Renew" })
			.click();
		await expect(dialog(page)).toBeVisible();
		await dialog(page).getByRole("button", { name: "Renew" }).click();
		await expect(dialog(page).getByText(/Payment confirmed/i)).toBeVisible({
			timeout: 45_000,
		});
	});

	test("list a handle for sale", async ({ page }) => {
		const seed = freshSeed();
		await registerHandle(seed, `home${uniq()}`, true);
		const handle = `sell${uniq()}`;
		await registerHandle(seed, handle, false);
		await signInSession(page, seed);
		await openTab(page, "Trading");
		// Gate on the signed-in wallet's identities being loaded — listing-card
		// Buy/Offer actions depend on canActAsBuyer, and the owner cards depend on
		// the same reverse lookup.
		await expect(page.getByText("Your Identities")).toBeVisible({
			timeout: 25_000,
		});

		const card = ownedCard(page, handle);
		await card.getByRole("button", { name: "List for sale" }).click();
		const priceInput = card.getByPlaceholder(/Price|25\.00/i).first();
		await priceInput.fill("120000");
		await card.getByRole("button", { name: `List @${handle}` }).click();
		// createListing succeeds → the inline form panel closes (price input gone).
		// (The "Cancel listing" badge depends on a cached listings refetch, so we
		// assert the cache-independent success signal instead.)
		await expect(priceInput).toBeHidden({ timeout: 20_000 });
	});

	test("buy a fixed-price listing via the confirm dialog", async ({ page }) => {
		const { handle } = await seedListing("fixed");
		const buyerSeed = freshSeed();
		await registerHandle(buyerSeed, `buyer${uniq()}`, true);
		await signInSession(page, buyerSeed);
		await openTab(page, "Trading");
		// Gate on the signed-in wallet's identities being loaded — listing-card
		// Buy/Offer actions depend on canActAsBuyer, and the owner cards depend on
		// the same reverse lookup.
		await expect(page.getByText("Your Identities")).toBeVisible({
			timeout: 25_000,
		});

		await listingCard(page, handle).getByRole("button", { name: "Buy" }).click();
		await expect(dialog(page)).toBeVisible();
		await dialog(page).getByRole("button", { name: "Buy" }).click();
		await expect(dialog(page).getByText(/Payment confirmed/i)).toBeVisible({
			timeout: 45_000,
		});
	});

	test("place an auction bid via the confirm dialog", async ({ page }) => {
		const { handle } = await seedListing("auction");
		const bidderSeed = freshSeed();
		await registerHandle(bidderSeed, `bid${uniq()}`, true);
		await signInSession(page, bidderSeed);
		await openTab(page, "Trading");
		// Gate on the signed-in wallet's identities being loaded — listing-card
		// Buy/Offer actions depend on canActAsBuyer, and the owner cards depend on
		// the same reverse lookup.
		await expect(page.getByText("Your Identities")).toBeVisible({
			timeout: 25_000,
		});

		const card = listingCard(page, handle);
		await card.getByRole("button", { name: "Bid" }).click();
		await card.getByPlaceholder(/At least/i).fill("100000");
		await card.getByRole("button", { name: "Place bid" }).click();
		await expect(dialog(page)).toBeVisible();
		await dialog(page).getByRole("button", { name: "Place bid" }).click();
		await expect(dialog(page).getByText(/Payment confirmed/i)).toBeVisible({
			timeout: 45_000,
		});
	});

	test("make an offer via the confirm dialog", async ({ page }) => {
		const { handle } = await seedListing("fixed");
		const buyerSeed = freshSeed();
		await registerHandle(buyerSeed, `offr${uniq()}`, true);
		await signInSession(page, buyerSeed);
		await openTab(page, "Trading");
		// Gate on the signed-in wallet's identities being loaded — listing-card
		// Buy/Offer actions depend on canActAsBuyer, and the owner cards depend on
		// the same reverse lookup.
		await expect(page.getByText("Your Identities")).toBeVisible({
			timeout: 25_000,
		});

		const card = listingCard(page, handle);
		await card.getByRole("button", { name: "Offer" }).click();
		await card.getByPlaceholder(/Offer amount/i).fill("90000");
		await card.getByRole("button", { name: /^Offer on/ }).click();
		await expect(dialog(page)).toBeVisible();
		await dialog(page).getByRole("button", { name: "Submit offer" }).click();
		await expect(dialog(page).getByText(/Payment confirmed/i)).toBeVisible({
			timeout: 45_000,
		});
	});
});

import assert from "node:assert/strict";
import test from "node:test";

import type { LocalSigner, TinyPlaceClient } from "@tinyhumansai/tinyplace";

import { buyDomain } from "./agent.js";

const SIGNER = {
  agentId: "4S3656ssvbVpaD9yGMtwVj3e7qMZNuSSxuQuhXKccrQj",
  publicKeyBase64: "Mvzw9tEbDl4wl36Z5Yhg83IQTMwyzB8AWgBkf2EMjKw=",
} as unknown as LocalSigner;

const IDENTITY = {
  username: "@openclawtest",
  cryptoId: SIGNER.agentId,
  status: "active",
  registeredAt: "2026-06-17T00:00:00.000Z",
  expiresAt: "2027-06-17T00:00:00.000Z",
};

test("buyDomain (re-exported from the flagship SDK) registers and summarizes", async () => {
  let registerCalls = 0;
  let profileWrites = 0;
  const client = {
    registry: {
      register: (): Promise<unknown> => {
        registerCalls += 1;
        return Promise.resolve(IDENTITY);
      },
    },
    // The flagship buyDomain no longer does best-effort harness-key telemetry,
    // so this must NOT be called (the harnessKey rides on every request instead).
    users: {
      updateProfile: (): Promise<never> => {
        profileWrites += 1;
        return Promise.reject(new Error("updateProfile should not be called"));
      },
    },
  } as unknown as TinyPlaceClient;

  const result = await buyDomain(client, SIGNER, "openclawtest");

  assert.equal(registerCalls, 1);
  assert.equal(profileWrites, 0);
  assert.equal(result.username, "@openclawtest");
  assert.equal(result.status, "active");
});

//! Endpoint tests for `BroadcastsApi`, `ActivityApi`, and `A2AApi`. Each test
//! points the client at a catch-all mock, invokes a method, and asserts the
//! request method and path. Response bodies are permissive — the goal is to
//! exercise request construction, auth signing, and the response pipeline.

mod common;

