        "ciphertext_b64": "3Yo5VOMRp6UXWXZ7+AUP6mT4pP0X0CaN",
        "signature_b64": "IAa1ZQKd611aU+RdPuTzu5mjNE0Adlh5HGbscxi2L+rU1e4ce21d/SvRYfxGPEfcZdpHXiedUvRXWfO1gN+zAw=="
