/**
 * Identity, discovery, profile, and social-graph facade functions.
 *
 * Each is a thin `(client, signer, …)` wrapper over the low-level
 * `TinyPlaceClient` API modules that returns plain JSON-serializable data — so a
 * CLI can print it and an LLM can reason over it. Paid actions (buy/renew a
 * handle) settle their x402 challenge automatically via {@link withAutoPayment}.
 *
 * These consolidate the facades that previously lived in the OpenClaw plugin's
 * `agent.ts`; the plugin now re-exports them.
 */
import type { TinyPlaceClient } from "../client.js";
import { TinyPlaceError } from "../http.js";
import { normalizeHandle } from "./handles.js";
import { withAutoPayment } from "./x402-auto.js";
import type {
  AgentSigner,
  AvailabilityResult,
  BuyDomainResult,
  DiscoveredAgent,
  IdentityStatus,
  PollResult,
  ProfileSummary,
  ProfileUpdateInput,
  PublishCardInput,
  PublishCardResult,
  ReputationSummary,
  ResolveResult,
} from "./types.js";

/** Checks whether a `@handle` is available, and who owns it if not. */
export async function checkDomain(
  client: TinyPlaceClient,
  name: string,
): Promise<AvailabilityResult> {
  const handle = normalizeHandle(name);
  const response = await client.registry.get(handle);
  return {
    name: handle,
    available: response.available,
    owner: response.identity?.cryptoId,
  };
}

/**
 * Buys (registers) a `@handle`. Attempts the free path first; on an x402 402 it
 * signs the challenge and retries with payment (custodial settlement, same as the
 * website). Returns the paid amount/asset when a payment was made.
 */
export async function buyDomain(
  client: TinyPlaceClient,
  signer: AgentSigner,
  name: string,
  options: { primary?: boolean } = {},
): Promise<BuyDomainResult> {
  const username = normalizeHandle(name);
  const request = {
    username,
    cryptoId: signer.agentId,
    publicKey: signer.publicKeyBase64,
    primary: options.primary ?? true,
  };

  let paidAmount: string | undefined;
  let paidAsset: string | undefined;
  const identity = await withAutoPayment(
    signer,
    (payment) => {
      if (payment) {
        paidAmount = payment["amount"];
        paidAsset = payment["asset"];
      }
      return client.registry.register(
        payment ? { ...request, payment } : request,
      );
    },
    {
      metadata: {
        identity: username,
        purpose: "registration",
        publicKey: signer.publicKeyBase64,
      },
    },
  );

  return {
    ...summarize(identity),
    ...(paidAmount ? { paidAmount } : {}),
    ...(paidAsset ? { paidAsset } : {}),
  };
}

function summarize(identity: {
  username: string;
  cryptoId: string;
  status: string;
  registeredAt: string;
  expiresAt: string;
  registrationTx?: string;
}): BuyDomainResult {
  return {
    username: identity.username,
    cryptoId: identity.cryptoId,
    status: identity.status,
    registeredAt: identity.registeredAt,
    expiresAt: identity.expiresAt,
    registrationTx: identity.registrationTx,
  };
}

/** Publishes (or updates) the agent's discovery card in the Open Directory. */
export async function publishCard(
  client: TinyPlaceClient,
  signer: AgentSigner,
  input: PublishCardInput,
): Promise<PublishCardResult> {
  const now = new Date().toISOString();
  const card = {
    agentId: signer.agentId,
    cryptoId: signer.agentId,
    publicKey: signer.publicKeyBase64,
    name: input.name,
    description: input.description,
    username: input.username,
    url: input.url,
    skills: input.skills ?? [],
    createdAt: now,
    updatedAt: now,
  };
  const result = await client.directory.upsertAgent(
    signer.agentId,
    card as never,
  );
  return {
    agentId: result.agentId,
    name: result.name,
    username: result.username,
  };
}

/**
 * Polls the platform for anything the agent should react to: unread inbox items,
 * new encrypted messages, and recent network activity. Each read is independent
 * and best-effort, so one failing surface (e.g. no identity yet) does not blank
 * the others. Intended to be run on a schedule.
 */
export async function pollUpdates(
  client: TinyPlaceClient,
  signer: AgentSigner,
  options: { since?: string; activityLimit?: number } = {},
): Promise<PollResult> {
  const checkedAt = new Date().toISOString();

  let inbox: PollResult["inbox"] = null;
  try {
    const counts = (await client.inbox.counts()) as {
      unread?: number;
      total?: number;
    };
    inbox = { unread: counts.unread, total: counts.total };
  } catch {
    inbox = null;
  }

  let newMessages = 0;
  try {
    const messages = await client.messages.list(signer.agentId, 50);
    newMessages = messages.messages.length;
  } catch {
    newMessages = 0;
  }

  let recentActivity: PollResult["recentActivity"] = [];
  try {
    const activity = await client.activity.list({
      limit: options.activityLimit ?? 10,
      ...(options.since ? { since: options.since } : {}),
    });
    recentActivity = activity.events.map((event) => ({
      kind: event.kind,
      actor: event.actor,
      target: event.target,
      amount: event.amount,
      asset: event.asset,
      timestamp: event.timestamp,
    }));
  } catch {
    recentActivity = [];
  }

  return { checkedAt, inbox, newMessages, recentActivity };
}

/** Reverse-looks-up the agent's owned handles + whether it has a directory card. */
export async function identityStatus(
  client: TinyPlaceClient,
  signer: AgentSigner,
): Promise<IdentityStatus> {
  const response = (await client.directory.reverse(signer.agentId)) as {
    identities?: Array<{
      username: string;
      status: string;
      expiresAt: string;
      primary?: boolean;
    }>;
    agents?: Array<unknown>;
  };
  return {
    agentId: signer.agentId,
    handles: (response.identities ?? []).map((identity) => ({
      username: identity.username,
      status: identity.status,
      expiresAt: identity.expiresAt,
      primary: identity.primary ?? false,
    })),
    hasCard: (response.agents ?? []).length > 0,
  };
}

/**
 * Normalizes a skills array to plain names. The backend returns skills either as
 * bare strings or as `{ id, name }` objects depending on the route; the SDK type
 * only models strings, so coerce defensively.
 */
function skillNames(skills: unknown): Array<string> | undefined {
  if (!Array.isArray(skills)) return undefined;
  return skills.map((skill) => {
    if (typeof skill === "string") return skill;
    const record = skill as { name?: string; id?: string };
    return record.name ?? record.id ?? String(skill);
  });
}

/**
 * Lists / searches agents in the Open Directory. Filter by free-text `q`,
 * `skill`, or `tag`. Lets an agent find peers to message, hire, or follow.
 */
export async function discoverAgents(
  client: TinyPlaceClient,
  options: { q?: string; skill?: string; tag?: string; limit?: number } = {},
): Promise<Array<DiscoveredAgent>> {
  const response = await client.directory.listAgents({
    ...(options.q ? { q: options.q } : {}),
    ...(options.skill ? { skill: options.skill } : {}),
    ...(options.tag ? { tag: options.tag } : {}),
    limit: options.limit ?? 20,
  });
  return (response.agents ?? []).map((agent) => ({
    agentId: agent.agentId,
    name: agent.name,
    username: agent.username,
    description: agent.description,
    skills: skillNames(agent.skills),
  }));
}

/** Resolves a `@handle` to its owning wallet + directory card (if any). */
export async function resolveHandle(
  client: TinyPlaceClient,
  name: string,
): Promise<ResolveResult> {
  const handle = normalizeHandle(name);
  let response: Awaited<ReturnType<typeof client.directory.resolve>>;
  try {
    response = await client.directory.resolve(handle);
  } catch (error) {
    // An unregistered handle 404s; surface a clean not-found result rather than
    // throwing, so callers can branch on `found`.
    if (error instanceof TinyPlaceError && error.status === 404) {
      return { name: handle, found: false };
    }
    throw error;
  }
  const identity = response.identity;
  return {
    name: handle,
    found: Boolean(identity),
    ...(identity?.cryptoId ? { cryptoId: identity.cryptoId } : {}),
    ...(identity?.publicKey ? { publicKey: identity.publicKey } : {}),
    ...(identity?.status ? { status: identity.status } : {}),
    ...(response.agent?.name ? { agentName: response.agent.name } : {}),
  };
}

/** Reads a wallet's User profile (display name, bio, link, tags, email state). */
export async function getProfile(
  client: TinyPlaceClient,
  cryptoId: string,
): Promise<ProfileSummary> {
  const user = await client.users.get(cryptoId);
  return {
    cryptoId: user.cryptoId,
    displayName: user.displayName,
    bio: user.bio,
    link: user.link,
    tags: user.tags,
    actorType: user.actorType,
    emailVerified: user.emailVerified,
  };
}

/** Updates the agent's own wallet profile (signs the canonical user.profile). */
export async function setProfile(
  client: TinyPlaceClient,
  signer: AgentSigner,
  update: ProfileUpdateInput,
): Promise<{ cryptoId: string; displayName: string; bio: string }> {
  const user = await client.users.updateProfile(signer.agentId, {
    ...(update.displayName !== undefined
      ? { displayName: update.displayName }
      : {}),
    ...(update.bio !== undefined ? { bio: update.bio } : {}),
    ...(update.link !== undefined ? { link: update.link } : {}),
    ...(update.tags !== undefined ? { tags: update.tags } : {}),
    ...(update.avatarEmail !== undefined
      ? { avatarEmail: update.avatarEmail }
      : {}),
    ...(update.actorType !== undefined ? { actorType: update.actorType } : {}),
  });
  return {
    cryptoId: user.cryptoId,
    displayName: user.displayName,
    bio: user.bio,
  };
}

/**
 * Renews a `@handle` the agent owns. Renewal may be free or require an x402
 * payment — same custodial-settlement pattern as registration.
 */
export async function renewDomain(
  client: TinyPlaceClient,
  signer: AgentSigner,
  name: string,
): Promise<{ username: string; status: string; expiresAt: string }> {
  const handle = normalizeHandle(name);
  const identity = await withAutoPayment(
    signer,
    (payment) => client.registry.renew(handle, payment ? { payment } : {}),
    { metadata: { identity: handle, purpose: "renewal" } },
  );
  return {
    username: identity.username,
    status: identity.status,
    expiresAt: identity.expiresAt,
  };
}

/** Transfers a `@handle` the agent owns to another wallet (no payment). */
export async function transferDomain(
  client: TinyPlaceClient,
  name: string,
  recipient: { cryptoId: string; publicKey: string },
): Promise<{ username: string; cryptoId: string }> {
  const handle = normalizeHandle(name);
  const identity = await client.registry.transfer(handle, {
    cryptoId: recipient.cryptoId,
    publicKey: recipient.publicKey,
  });
  return { username: identity.username, cryptoId: identity.cryptoId };
}

/** Assigns or unassigns a handle as the wallet's primary identity. */
export async function setPrimaryHandle(
  client: TinyPlaceClient,
  name: string,
  primary: boolean,
): Promise<{ username: string; primary: boolean }> {
  const handle = normalizeHandle(name);
  const identity = primary
    ? await client.registry.assignPrimary(handle)
    : await client.registry.unassignPrimary(handle);
  return { username: identity.username, primary };
}

/** Follows another agent (personalized feed input). */
export async function followAgent(
  client: TinyPlaceClient,
  agentId: string,
): Promise<{ follower: string; followee: string }> {
  const follow = await client.follows.follow(agentId);
  return { follower: follow.follower, followee: follow.followee };
}

/** Unfollows an agent. */
export async function unfollowAgent(
  client: TinyPlaceClient,
  agentId: string,
): Promise<{ unfollowed: string }> {
  await client.follows.unfollow(agentId);
  return { unfollowed: agentId };
}

/** Follower / following counts for an agent. */
export async function followStats(
  client: TinyPlaceClient,
  agentId: string,
): Promise<{ agentId: string; followerCount: number; followingCount: number }> {
  const stats = await client.follows.stats(agentId);
  return {
    agentId: stats.agentId,
    followerCount: stats.followerCount,
    followingCount: stats.followingCount,
  };
}

/** The agent's personalized activity feed (events from agents it follows). */
export async function feed(
  client: TinyPlaceClient,
  options: { limit?: number; since?: string } = {},
): Promise<PollResult["recentActivity"]> {
  const response = await client.follows.feed({
    limit: options.limit ?? 20,
    ...(options.since ? { since: options.since } : {}),
  });
  return response.events.map((event) => ({
    kind: event.kind,
    actor: event.actor,
    target: event.target,
    amount: event.amount,
    asset: event.asset,
    timestamp: event.timestamp,
  }));
}

/** Reputation score + recent review count for an agent. */
export async function getReputation(
  client: TinyPlaceClient,
  agentId: string,
): Promise<ReputationSummary> {
  const score = await client.reputation.getScore(agentId);
  let reviewCount = 0;
  try {
    const reviews = await client.reputation.getReviews(agentId);
    reviewCount = reviews.reviews.length;
  } catch {
    reviewCount = 0;
  }
  return {
    agentId: score.agentId,
    score: score.score,
    breakdown: score.breakdown,
    reviewCount,
  };
}

// Cross-language interop vector generator for the tiny.place Signal port.
//
// PROVENANCE: this script imports and executes the REAL flagship TypeScript
// Signal implementation in `sdk/typescript/src/signal/*.ts` (the only SDK with
// full Signal E2E crypto), compiled verbatim with the SDK's own `tsc`. The
// modules pull their primitives from `@noble/curves` and `@noble/hashes`. The
// emitted vectors are therefore genuine TypeScript-SDK output, NOT values
// recomputed from the Python port. The companion Python test
// `tests/test_signal_interop.py` pins these vectors and asserts the Python
// implementation reproduces / consumes them byte-for-byte.
//
// Reproduce (from sdk/typescript):
//   npm install --no-save @noble/curves@^2.2.0 @noble/hashes@^2.2.0
//   node_modules/.bin/tsc src/signal/*.ts --outDir .sigbuild --module ESNext \
//     --target ES2020 --moduleResolution bundler --skipLibCheck --declaration false
//   node ../python/tests/vectors/gen_signal_vectors.mjs > \
//     ../python/tests/vectors/signal_vectors.json
//
// `.sigbuild/` and `node_modules/` are transient (never committed); only this
// script and its JSON output are versioned. All inputs are fixed (no randomness)
// so the committed JSON is fully reproducible.

// @noble + the compiled signal modules live under sdk/typescript (transient,
// see the reproduce note). Resolve them via paths relative to this script so
// the generator runs regardless of the process cwd.
import { x25519, ed25519 } from "../../../typescript/node_modules/@noble/curves/ed25519.js";

import {
  kdfRootKey,
  kdfChainKey,
  deriveMessageKeys,
  x25519SharedSecret,
  encrypt,
  decrypt,
  computeHmac,
  toBase64,
} from "../../../typescript/.sigbuild/signal/crypto.js";
import { x3dhRespond } from "../../../typescript/.sigbuild/signal/x3dh.js";
import { ratchetEncrypt, ratchetDecrypt } from "../../../typescript/.sigbuild/signal/ratchet.js";
import {
  GroupSenderKey,
  GroupSenderKeyReceiver,
} from "../../../typescript/.sigbuild/signal/sender-key.js";

const hex = (u8) => Buffer.from(u8).toString("hex");
const fromHex = (h) => Uint8Array.from(Buffer.from(h, "hex"));
const utf8 = (s) => new TextEncoder().encode(s);

// Deterministic 32-byte filler.
const fill = (b) => new Uint8Array(32).fill(b);

const X3DH_INFO = utf8("WhisperText");
const PADDING = new Uint8Array(32).fill(0xff);

function concat(...arrays) {
  let total = 0;
  for (const a of arrays) total += a.length;
  const out = new Uint8Array(total);
  let off = 0;
  for (const a of arrays) {
    out.set(a, off);
    off += a.length;
  }
  return out;
}

// X25519 keypair from a fixed 32-byte private scalar (clamped by getPublicKey).
function x25519Pair(priv) {
  return { privateKey: priv, publicKey: x25519.getPublicKey(priv) };
}

const vectors = {};

// --------------------------------------------------------------------------
// 1. crypto KDFs / AEAD primitives (pure functions, exact byte compare)
// --------------------------------------------------------------------------
{
  const rootKey = fill(0x11);
  const dhOutput = fill(0x22);
  const { rootKey: nextRoot, chainKey } = kdfRootKey(rootKey, dhOutput);

  const chainIn = fill(0x33);
  const ck = kdfChainKey(chainIn);

  const messageKey = fill(0x44);
  const mk = deriveMessageKeys(messageKey);

  const hmacKey = fill(0x55);
  const hmacData = utf8("tiny.place signal interop");

  const aeadMessageKey = fill(0x66);
  const aeadPlaintext = utf8("hello from the TypeScript SDK \u{1f510}");
  const aeadAd = utf8("associated-data");
  const aeadCt = await encrypt(aeadMessageKey, aeadPlaintext, aeadAd);

  // Empty-plaintext edge case (PKCS#7 pads a full block).
  const emptyCt = await encrypt(aeadMessageKey, new Uint8Array(0), new Uint8Array(0));

  vectors.crypto = {
    kdf_root_key: {
      root_key: hex(rootKey),
      dh_output: hex(dhOutput),
      next_root_key: hex(nextRoot),
      chain_key: hex(chainKey),
    },
    kdf_chain_key: {
      chain_key_in: hex(chainIn),
      next_chain_key: hex(ck.chainKey),
      message_key: hex(ck.messageKey),
    },
    derive_message_keys: {
      message_key: hex(messageKey),
      enc_key: hex(mk.encKey),
      mac_key: hex(mk.macKey),
      iv: hex(mk.iv),
    },
    compute_hmac: {
      key: hex(hmacKey),
      data: hex(hmacData),
      mac: hex(computeHmac(hmacKey, hmacData)),
    },
    aead: {
      message_key: hex(aeadMessageKey),
      plaintext: hex(aeadPlaintext),
      associated_data: hex(aeadAd),
      ciphertext: hex(aeadCt),
    },
    aead_empty: {
      message_key: hex(aeadMessageKey),
      plaintext: "",
      associated_data: "",
      ciphertext: hex(emptyCt),
    },
  };
}

// --------------------------------------------------------------------------
// 2. X3DH shared secret (initiator math, deterministic via fixed ephemeral)
// --------------------------------------------------------------------------
// x3dhInitiate() generates a random ephemeral internally, so we reproduce the
// exact initiator computation here using the real DH + HKDF primitives with a
// FIXED ephemeral, and additionally drive the real x3dhRespond() to prove both
// directions reach the same secret.
{
  const aliceIdentity = x25519Pair(fill(0xa1));
  const aliceEphemeral = x25519Pair(fill(0xa2));
  const bobIdentity = x25519Pair(fill(0xb1));
  const bobSignedPreKey = x25519Pair(fill(0xb2));
  const bobOneTimePreKey = x25519Pair(fill(0xb3));

  // Initiator side, with one-time pre-key (4 DHs).
  const dh1 = x25519SharedSecret(aliceIdentity.privateKey, bobSignedPreKey.publicKey);
  const dh2 = x25519SharedSecret(aliceEphemeral.privateKey, bobIdentity.publicKey);
  const dh3 = x25519SharedSecret(aliceEphemeral.privateKey, bobSignedPreKey.publicKey);
  const dh4 = x25519SharedSecret(aliceEphemeral.privateKey, bobOneTimePreKey.publicKey);
  const concat4 = concat(PADDING, dh1, dh2, dh3, dh4);
  const { hkdf } = await import("../../../typescript/node_modules/@noble/hashes/hkdf.js");
  const { sha256 } = await import("../../../typescript/node_modules/@noble/hashes/sha2.js");
  const secretWithOtk = hkdf(sha256, concat4, new Uint8Array(32), X3DH_INFO, 32);

  // Without one-time pre-key (3 DHs).
  const concat3 = concat(PADDING, dh1, dh2, dh3);
  const secretNoOtk = hkdf(sha256, concat3, new Uint8Array(32), X3DH_INFO, 32);

  // Drive the REAL responder to confirm reciprocity (Bob recomputes Alice's secret).
  const bobSession = x3dhRespond(
    bobIdentity,
    bobSignedPreKey,
    aliceIdentity.publicKey,
    aliceEphemeral.publicKey,
    bobOneTimePreKey,
  );

  vectors.x3dh = {
    alice_identity_priv: hex(aliceIdentity.privateKey),
    alice_identity_pub: hex(aliceIdentity.publicKey),
    alice_ephemeral_priv: hex(aliceEphemeral.privateKey),
    alice_ephemeral_pub: hex(aliceEphemeral.publicKey),
    bob_identity_priv: hex(bobIdentity.privateKey),
    bob_identity_pub: hex(bobIdentity.publicKey),
    bob_signed_pre_key_priv: hex(bobSignedPreKey.privateKey),
    bob_signed_pre_key_pub: hex(bobSignedPreKey.publicKey),
    bob_one_time_pre_key_priv: hex(bobOneTimePreKey.privateKey),
    bob_one_time_pre_key_pub: hex(bobOneTimePreKey.publicKey),
    shared_secret_with_otk: hex(secretWithOtk),
    shared_secret_no_otk: hex(secretNoOtk),
    // The responder must reach the identical secret.
    responder_root_key_with_otk: hex(bobSession.rootKey),
  };
}

// --------------------------------------------------------------------------
// 3. Double Ratchet: Alice encrypts -> vector; Bob (Python) decrypts.
// --------------------------------------------------------------------------
// Build deterministic, symmetric initial sessions (shared root key, Alice's
// ratchet keypair fixed, Bob holds Alice's public key as dhRecvPublicKey). The
// first ratchetEncrypt runs the deterministic initial DH-ratchet step (no key
// generation), so the produced messages are fully reproducible.
{
  const rootKey = fill(0x77);
  const aliceRatchet = x25519Pair(fill(0xc1));
  const associatedData = utf8("alice->bob");

  // Alice's sending session: she sends first, so she needs Bob's recv key.
  // Mirror x3dhInitiate's handoff: dhRecvPublicKey = Bob's signed pre-key.
  const bobRatchet = x25519Pair(fill(0xc2));

  const aliceSession = {
    dhSendKeyPair: aliceRatchet,
    dhRecvPublicKey: bobRatchet.publicKey,
    rootKey: rootKey,
    sendChainKey: null,
    recvChainKey: null,
    sendMessageNumber: 0,
    recvMessageNumber: 0,
    previousChainLength: 0,
    skippedKeys: new Map(),
  };

  const plaintexts = ["ratchet message one", "second message", "third \u{1f680}"];
  const messages = [];
  for (const p of plaintexts) {
    const m = await ratchetEncrypt(aliceSession, utf8(p), associatedData);
    messages.push({
      plaintext: hex(utf8(p)),
      header_public_key: hex(m.header.publicKey),
      header_previous_chain_length: m.header.previousChainLength,
      header_message_number: m.header.messageNumber,
      ciphertext: hex(m.ciphertext),
    });
  }

  // Reverse direction: have Bob decrypt the first message with the REAL TS
  // ratchetDecrypt to prove the chosen initial state is self-consistent, then
  // record nothing extra (Python re-derives Bob's state identically).
  const bobSession = {
    dhSendKeyPair: bobRatchet,
    dhRecvPublicKey: null,
    rootKey: rootKey,
    sendChainKey: null,
    recvChainKey: null,
    sendMessageNumber: 0,
    recvMessageNumber: 0,
    previousChainLength: 0,
    skippedKeys: new Map(),
  };
  const first = messages[0];
  const decoded = await ratchetDecrypt(
    bobSession,
    {
      header: {
        publicKey: fromHex(first.header_public_key),
        previousChainLength: first.header_previous_chain_length,
        messageNumber: first.header_message_number,
      },
      ciphertext: fromHex(first.ciphertext),
    },
    associatedData,
  );
  if (Buffer.from(decoded).toString("utf8") !== plaintexts[0]) {
    throw new Error("TS ratchet self-check failed");
  }

  vectors.ratchet = {
    root_key: hex(rootKey),
    alice_ratchet_priv: hex(aliceRatchet.privateKey),
    alice_ratchet_pub: hex(aliceRatchet.publicKey),
    bob_ratchet_priv: hex(bobRatchet.privateKey),
    bob_ratchet_pub: hex(bobRatchet.publicKey),
    associated_data: hex(associatedData),
    messages,
  };
}

// --------------------------------------------------------------------------
// 4. Sender Keys (group messaging): real GroupSenderKey encrypt + sign.
// --------------------------------------------------------------------------
// GroupSenderKey.create() randomizes, so build a deterministic instance from a
// fixed serialized state (the public restore() path), then encrypt a few
// messages. Python's receiver decrypts from the same distribution.
{
  const chainKey = fill(0xd1);
  const signingSeed = fill(0xd2); // ed25519 secret key (noble: 32-byte seed)
  const signingPub = ed25519.getPublicKey(signingSeed);

  const sender = GroupSenderKey.restore({
    chainKey: toBase64(chainKey),
    iteration: 0,
    signaturePrivateKey: [REDACTED],
    signaturePublicKey: toBase64(signingPub),
  });

  const distribution = sender.distribution();

  const plaintexts = ["group hello", "group second", "group third"];
  const messages = [];
  for (const p of plaintexts) {
    const m = await sender.encrypt(utf8(p));
    messages.push({
      plaintext: hex(utf8(p)),
      iteration: m.iteration,
      ciphertext_b64: m.ciphertext,
      signature_b64: m.signature,
    });
  }

  // Self-check with the real receiver.
  const receiver = GroupSenderKeyReceiver.fromDistribution(distribution);
  for (let i = 0; i < messages.length; i++) {
    const pt = await receiver.decrypt({
      iteration: messages[i].iteration,
      ciphertext: messages[i].ciphertext_b64,
      signature: messages[i].signature_b64,
    });
    if (Buffer.from(pt).toString("utf8") !== plaintexts[i]) {
      throw new Error("TS sender-key self-check failed");
    }
  }

  vectors.sender_key = {
    chain_key: hex(chainKey),
    signing_seed: hex(signingSeed),
    signing_public_key: hex(signingPub),
    distribution: {
      chain_key_b64: distribution.chainKey,
      iteration: distribution.iteration,
      signature_public_key_b64: distribution.signaturePublicKey,
    },
    messages,
  };
}

process.stdout.write(JSON.stringify(vectors, null, 2) + "\n");

import { beforeEach, describe, expect, it } from "vitest";
import { LocalSigner, Signer } from "@tinyhumansai/tinyplace";

import {
	setAuthSession,
	signX402ChallengeAuthorization,
	signX402ChallengePaymentMap,
	type X402ChallengePayment,
} from "./auth-payment";
import { useAuthStore } from "@src/store/auth";

class CachedAuthTokenSigner extends Signer {
	public readonly agentId = "cached-siws-wallet";
	public readonly publicKeyBase64 = "cached-siws-public-key";

	public sign(): Uint8Array {
		return new TextEncoder().encode("cached-siws-proof");
	}

	public getX25519KeyPair(): never {
		throw new Error("not used in auth-payment tests");
	}
}

describe("auth payment signing", () => {
	beforeEach(() => {
		useAuthStore.getState().clearSession();
	});

	it("standardizes x402 challenge defaults and signer metadata", async () => {
		const signer = await LocalSigner.fromSeed(new Uint8Array(32).fill(7));
		const authorization = await signX402ChallengeAuthorization({
			fallbackFrom: signer.agentId,
			metadata: { purpose: "test" },
			noncePrefix: "unit",
			payment: {
				scheme: "exact",
				network: "solana:mainnet",
				asset: "USDC",
				amount: "123",
				from: "",
				to: "treasury",
			},
			signer,
		});

		expect(authorization).toMatchObject({
			scheme: "exact",
			network: "solana:mainnet",
			asset: "USDC",
			amount: "123",
			from: signer.agentId,
			to: "treasury",
		});
		expect(authorization.expiresAt).not.toBe("");
		expect(authorization.nonce).toMatch(/^unit_/);
		expect(authorization.metadata).toMatchObject({
			publicKey: signer.publicKeyBase64,
			purpose: "test",
		});
		expect(authorization.signature).not.toBe("");
	});

	it("returns the backend payment-map shape", async () => {
		const signer = await LocalSigner.fromSeed(new Uint8Array(32).fill(8));
		const payment = await signX402ChallengePaymentMap({
			fallbackFrom: signer.agentId,
			noncePrefix: "map",
			payment: {
				scheme: "exact",
				network: "solana:mainnet",
				asset: "USDC",
				amount: "456",
				from: signer.agentId,
				to: "seller",
			},
			signer,
		});

		expect(payment).toMatchObject({
			scheme: "exact",
			network: "solana:mainnet",
			asset: "USDC",
			amount: "456",
			from: signer.agentId,
			to: "seller",
			"metadata.publicKey": signer.publicKeyBase64,
		});
		expect(payment["signature"]).not.toBe("");
	});

	it("defaults x402 signing to the direct identity signer, not the cached SIWS auth signer", async () => {
		const identity = await LocalSigner.fromSeed(new Uint8Array(32).fill(9));
		const apiAuth = new CachedAuthTokenSigner();
		const payment: X402ChallengePayment = {
			scheme: "exact",
			network: "solana:mainnet",
			asset: "USDC",
			amount: "789",
			from: identity.agentId,
			to: "seller",
			nonce: "fixed-nonce",
			expiresAt: "2026-06-18T12:05:00.000Z",
		};
		setAuthSession(apiAuth, identity);

		const defaultAuthorization = await signX402ChallengeAuthorization({
			fallbackFrom: identity.agentId,
			noncePrefix: "default",
			payment,
		});
		const identityAuthorization = await signX402ChallengeAuthorization({
			fallbackFrom: identity.agentId,
			noncePrefix: "identity",
			payment,
			signer: identity,
		});

		expect(defaultAuthorization.signature).toBe(
			identityAuthorization.signature
		);
		expect(defaultAuthorization.metadata).toMatchObject({
			publicKey: identity.publicKeyBase64,
		});
		expect(defaultAuthorization.signature).not.toBe(btoa("cached-siws-proof"));
	});
});

import { describe, expect, it } from "vitest";

import { formatFee, getAnnualFee, PRICING_TIERS } from "./domain-pricing";

// Map each PRICING_TIERS row to a representative handle length so we can assert
// the computed fee preview matches the advertised tier. The 5+ tier is covered
// by an 8-char example handle.
const TIER_HANDLES: Array<{ handle: string; tierIndex: number }> = [
	{ handle: "@x", tierIndex: 0 },
	{ handle: "@ai", tierIndex: 1 },
	{ handle: "@bot", tierIndex: 2 },
	{ handle: "@data", tierIndex: 3 },
	{ handle: "@analyst", tierIndex: 4 },
];

describe("DomainRegistration fee display", () => {
	it("renders a 1-char handle fee consistent with PRICING_TIERS (not ~1000x off)", () => {
		expect(formatFee(getAnnualFee("@x"))).toBe(PRICING_TIERS[0]?.fee);
		expect(formatFee(getAnnualFee("@x"))).toBe("2,000 USDC");
	});

	it("keeps every tier's preview consistent with its advertised fee", () => {
		for (const { handle, tierIndex } of TIER_HANDLES) {
			expect(formatFee(getAnnualFee(handle))).toBe(
				PRICING_TIERS[tierIndex]?.fee
			);
		}
	});

	it("uses the published production price for the 5+ tier", () => {
		expect(formatFee(getAnnualFee("@analyst"))).toBe("1 USDC");
	});
});

